blocos.conteudo:
{
  name: 'buscar_oficinas',
  title: 'Buscar oficinas',
  description: 'Lista as oficinas da agenda por tema. Só lê: não reserva nada. Use apenasComVaga=true para ver só as que ainda têm vaga.',
  inputSchema: {
    type: 'object',
    properties: {
      tema: { type: 'string', enum: TEMAS, description: 'Tema da oficina.' },
      apenasComVaga: { type: 'boolean', description: 'true = só oficinas com vaga.' }
    },
    additionalProperties: false
  },
  annotations: { readOnlyHint: true },
  execute: comErroUtil(async input => {
    const lista = agenda.buscar(input);
    ui.mostrarResultados(lista, input);   // a pessoa vê o mesmo que o agente recebeu
    return { total: lista.length, oficinas: lista };
  })
}

const mc = document.modelContext;   // nombre actual (16/10/2026)
if (!mc || typeof mc.registerTool !== 'function') {
  aviso?.('Este navegador não expõe WebMCP. Tudo funciona pelo formulário.');
  return { modo: 'sem', registradas: 0 };
}
const pagina = new AbortController();
addEventListener('pagehide', () => pagina.abort(), { once: true });
await registrar(mc, defs, pagina.signal);

cd ~/projetos/formacao-webmcp-site-v72/kit
E=${TMPDIR:-/tmp}/ensaio-webmcp-site/a3; rm -rf $E; mkdir -p $E; cp -r pagina/. $E/
cat > $E/extras.mjs <<'FIM'
export function extras(agenda) {
  return [{
    name: 'contar_vagas',
    description: 'Soma as vagas livres das oficinas de um tema. Só lê: não reserva nada.',
    inputSchema: {
      type: 'object',
      properties: { tema: { type: 'string', enum: ['html', 'javascript', 'webmcp', 'mcp'], description: 'Tema da oficina.' } },
      required: ['tema'],
      additionalProperties: false
    },
    annotations: { readOnlyHint: true },
    async execute({ tema }) {
      const lista = agenda.buscar({ tema });
      return { tema, vagas: lista.reduce((soma, o) => soma + o.vagas, 0) };
    }
  }];
}
FIM
PAGINA=$E node scripts/listar.mjs nativo | tail -1
PAGINA=$E node scripts/executar.mjs nativo contar_vagas '{"tema":"html"}'; echo "saída: $?"
